(async()=>{const out=[];for(const visible of [false,true]){const g=new OffscreenCanvas(2,2).getContext('webgl2',{antialias:false}),p=g.createProgram();for(const [t,src]of [[g.VERTEX_SHADER,'#version 300 es\nvoid main(){gl_Position=vec4(float(gl_VertexID==1)*2.-1.,float(gl_VertexID==2)*2.-1.,0.,1.);}'],[g.FRAGMENT_SHADER,'#version 300 es\nprecision mediump float;out vec4 color;void main(){color=vec4(1.);}']]){const s=g.createShader(t);g.shaderSource(s,src);g.compileShader(s);g.attachShader(p,s)}g.linkProgram(p);g.useProgram(p);g.enable(g.SCISSOR_TEST);g.scissor(0,0,visible?2:0,2);const q=g.createQuery();g.beginQuery(g.ANY_SAMPLES_PASSED,q);g.drawArrays(g.TRIANGLES,0,3);g.endQuery(g.ANY_SAMPLES_PASSED);g.finish();await new Promise(r=>setTimeout(r,50));out.push([g.getQueryParameter(q,g.QUERY_RESULT_AVAILABLE),g.getQueryParameter(q,g.QUERY_RESULT),g.getError()])}return out})()

